def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    def runs(seq):
        out = []
        i = 0
        while i < len(seq):
            if seq[i] == bg:
                i += 1
                continue
            color = seq[i]
            j = i + 1
            while j < len(seq) and seq[j] == color:
                j += 1
            out.append((i, j - 1, color))
            i = j
        return out

    candidates = []
    for a, b in ((runs(grid[0]), runs(grid[-1])),
                 (runs([grid[r][0] for r in range(h)]),
                  runs([grid[r][-1] for r in range(h)]))):
        for x in a:
            for y in b:
                if x[2] == y[2] and x[1] - x[0] == y[1] - y[0]:
                    candidates.append((x[1] - x[0] + 1, x, y))

    if not candidates:
        return [row[:] for row in grid]

    _, first, second = max(candidates, key=lambda z: z[0])
    horizontal = first[0] == 0 and second[0] == 0  # replaced below for clarity
    # The runs themselves are axis intervals; decide orientation by which edges matched.
    top_pair = any(
        x == first and y == second
        for x in runs(grid[0]) for y in runs(grid[-1])
    )
    horizontal = top_pair
    marker_color = first[2]
    lo1, lo2 = first[0], second[0]
    length = first[1] - first[0] + 1

    dots = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg and grid[r][c] != marker_color:
                dots.append((r, c, grid[r][c]))

    offsets = {}
    for r, c, color in dots:
        axis = c if horizontal else r
        if lo1 <= axis < lo1 + length:
            offsets[axis - lo1] = color
        elif lo2 <= axis < lo2 + length:
            offsets[axis - lo2] = color

    out = [row[:] for row in grid]
    dot_cells = {(r, c) for r, c, _ in dots}

    if horizontal:
        sides = [(0, lo1, 1), (h - 1, lo2, -1)]
        for offset, color in offsets.items():
            for edge, start, direction in sides:
                c = start + offset
                r = edge + direction
                while 0 <= r < h:
                    if (r, c) in dot_cells:
                        out[r][c] = 4
                        break
                    if grid[r][c] != bg:
                        break
                    out[r][c] = color
                    r += direction
    else:
        sides = [(0, lo1, 1), (w - 1, lo2, -1)]
        for offset, color in offsets.items():
            for edge, start, direction in sides:
                r = start + offset
                c = edge + direction
                while 0 <= c < w:
                    if (r, c) in dot_cells:
                        out[r][c] = 4
                        break
                    if grid[r][c] != bg:
                        break
                    out[r][c] = color
                    c += direction

    return out
